(function(root){'use strict';
const ATLAS='assets/warrior/skills-atlas.png';
// Independent subtextures from the transparent production atlas, created only at load time.
const REFERENCE_RECTS=Object.freeze({sword:[10,0,300,420],wave:[325,0,310,425],quake:[642,35,310,365],ghost:[965,0,310,420],orbitIcon:[5,435,310,330],waveIcon:[325,435,310,330],quakeIcon:[645,435,310,330],ghostIcon:[965,435,310,330],masteryIcon:[5,835,310,335],furyIcon:[325,835,310,335],armorIcon:[645,835,310,335]});
const RECTS=Object.freeze(Object.fromEntries(Object.entries(REFERENCE_RECTS).map(([id,rect])=>[id,Object.freeze(rect.map(v=>Math.floor(v*1254/1280)))])));
let image=null;
function paths(){return [ATLAS]}
function configure(resources){image=resources.get(ATLAS)||null}
function icon(name){const r=RECTS[name+'Icon'];if(!r)return '';return '<svg class="rpg-icon warrior-skill-icon" viewBox="'+r.join(' ')+'" aria-hidden="true"><image href="'+ATLAS+'" width="1254" height="1254"/></svg>'}
async function createPixi(PIXI,parent){const sheet=await PIXI.Assets.load(ATLAS);sheet.baseTexture.scaleMode=PIXI.SCALE_MODES.NEAREST;const textures={};for(const [id,r] of Object.entries(RECTS))textures[id]=new PIXI.Texture(sheet.baseTexture,new PIXI.Rectangle(...r));const ground=new PIXI.Container(),upper=new PIXI.Container();parent.addChildAt(ground,0);parent.addChild(upper);
 const sprite=(layer,key)=>{const s=new PIXI.Sprite(textures[key]);s.anchor.set(.5);s.visible=false;layer.addChild(s);return s},quake=sprite(ground,'quake'),mask=new PIXI.Graphics(),ring=new PIXI.Graphics();ground.addChild(mask);ground.addChild(ring);quake.mask=mask;const trails=new PIXI.Graphics();upper.addChild(trails);return {ground,upper,quake,mask,ring,trails,orbits:Array.from({length:3},()=>sprite(upper,'sword')),ghost:sprite(upper,'ghost'),waves:Array.from({length:4},()=>sprite(upper,'wave')),quakeSerial:-1};
}
function place(sprite,x,y,w,h,angle,alpha=1){sprite.visible=true;sprite.position.set(x,y);sprite.width=w*1.3225;sprite.height=h*1.3225;sprite.rotation=angle;sprite.alpha=alpha}
function drawPixi(rig,party){const state=party.warrior;if(!rig||!state)return;if(rig.party!==party){rig.party=party;rig.quakeSerial=-1}rig.trails.clear();rig.ring.clear();for(let i=0;i<3;i++){const sword=state.orbits[i],sprite=rig.orbits[i];sprite.visible=sword.active;if(!sword.active)continue;place(sprite,sword.x,sword.y,48,94,sword.angle);const a=sword.angle-Math.PI/2;rig.trails.lineStyle(6,0xfaa348,.42).moveTo(sword.x-Math.cos(a-.3)*7,sword.y-Math.sin(a-.3)*7).lineTo(sword.prevX,sword.prevY);rig.trails.lineStyle(2,0xffd785,.7).moveTo(sword.x,sword.y).lineTo(sword.prevX,sword.prevY)}
 const g=state.ghost;rig.ghost.visible=g.visible;if(g.visible){place(rig.ghost,g.x,g.y,54,100,g.angle,.85+.1*Math.sin(party.time*6));for(let i=0;i<5;i++){const at=(g.trailHead-1-i+6)%6,x=g.trail[at*2],y=g.trail[at*2+1];if(!x&&!y)continue;rig.trails.lineStyle(5,0x68cfff,.36*(1-i/6));if(i===0)rig.trails.moveTo(g.x,g.y);rig.trails.lineTo(x,y)}}
 let count=0;for(const s of party.projectiles){if(!s.active||s.kind!=='crescent')continue;const sprite=rig.waves[count++];if(!sprite)break;place(sprite,s.x,s.y,76,86*(s.visualWidth||1),s.angle);rig.trails.lineStyle(3,0xffc56c,.4).moveTo(s.prevX,s.prevY).lineTo(s.x,s.y)}for(let i=count;i<rig.waves.length;i++)rig.waves[i].visible=false;
 const f=state.quake;rig.quake.visible=f.life>0;rig.mask.visible=f.life>0;if(f.life>0){const q=f.life/f.duration,progress=1-q;place(rig.quake,f.x,f.y,f.radius*2,f.radius*2,0,Math.min(.8,q*1.3));if(rig.quakeSerial!==f.serial){rig.quakeSerial=f.serial;rig.mask.clear().beginFill(0xffffff,1);for(let i=0;i<=f.rays.length;i++){const at=i%f.rays.length,a=at/f.rays.length*Math.PI*2,x=f.x+Math.cos(a)*f.rays[at]*1.3225,y=f.y+Math.sin(a)*f.rays[at]*1.3225;if(!i)rig.mask.moveTo(x,y);else rig.mask.lineTo(x,y)}rig.mask.closePath().endFill()}rig.ring.lineStyle(3+q*4,0xffc47c,q);for(let i=0;i<=f.rays.length;i++){const at=i%f.rays.length,a=at/f.rays.length*Math.PI*2,d=Math.min(f.rays[at],f.radius*(.2+progress*.8))*1.3225,x=f.x+Math.cos(a)*d,y=f.y+Math.sin(a)*d;if(!i)rig.ring.moveTo(x,y);else rig.ring.lineTo(x,y)}}
}
function canvasSprite(ctx,key,x,y,w,h,angle,alpha=1){if(!image?.naturalWidth)return;const r=RECTS[key];ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.globalAlpha=alpha;ctx.drawImage(image,...r,-w*.66125,-h*.66125,w*1.3225,h*1.3225);ctx.restore()}
function drawCanvas(ctx,party){const state=party.warrior;if(!state||!image)return;ctx.save();ctx.shadowBlur=0;const f=state.quake;if(f.life>0){ctx.save();ctx.beginPath();for(let i=0;i<=f.rays.length;i++){const j=i%f.rays.length,a=j/f.rays.length*Math.PI*2,x=f.x+Math.cos(a)*f.rays[j]*1.3225,y=f.y+Math.sin(a)*f.rays[j]*1.3225;if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath();ctx.clip();canvasSprite(ctx,'quake',f.x,f.y,f.radius*2,f.radius*2,0,f.life/f.duration*.8);ctx.restore()}
 for(const sword of state.orbits)if(sword.active){ctx.strokeStyle='#ffa54b';ctx.globalAlpha=.5;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(sword.prevX,sword.prevY);ctx.lineTo(sword.x,sword.y);ctx.stroke();canvasSprite(ctx,'sword',sword.x,sword.y,48,94,sword.angle)}
 if(state.ghost.visible){const g=state.ghost;ctx.strokeStyle='#69d4ff';ctx.lineWidth=4;ctx.globalAlpha=.45;ctx.beginPath();ctx.moveTo(g.x,g.y);for(let i=0;i<5;i++){const j=(g.trailHead-1-i+6)%6,x=g.trail[j*2],y=g.trail[j*2+1];if(x||y)ctx.lineTo(x,y)}ctx.stroke();canvasSprite(ctx,'ghost',g.x,g.y,54,100,g.angle,.9)}
 for(const s of party.projectiles)if(s.active&&s.kind==='crescent')canvasSprite(ctx,'wave',s.x,s.y,76,86*(s.visualWidth||1),s.angle);ctx.restore();
}
root.MicroverseWarriorVisuals={ATLAS,RECTS,paths,configure,icon,createPixi,drawPixi,drawCanvas};
})(typeof globalThis!=='undefined'?globalThis:this);
